                var nextIdent = Advance();
                keywordName += "-" + nextIdent.Text;
                endSpan = nextIdent.Span;
            }

            var span = colonToken.Span.Union(endSpan);
            if (!allowKeyword)
            {
                _diagnostics.ReportError(span, DiagnosticCode.InvalidLispExpression,
